import sys


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    n, m = data[0], data[1]
    edges = [
        (data[index + 2], data[index] - 1, data[index + 1] - 1)
        for index in range(2, len(data), 3)
    ]
    del data
    edges.sort()

    if m < n:
        print(-1)
        return

    sys.setrecursionlimit(2 * n + 100)

    def possible(edge_count):
        adjacency = [[] for _ in range(n)]
        right_seen = bytearray(n)

        for index in range(edge_count):
            _, airport, factory = edges[index]
            adjacency[airport].append(factory)
            right_seen[factory] = 1

        if not all(right_seen) or any(not neighbors for neighbors in adjacency):
            return False

        left_match = [-1] * n
        right_match = [-1] * n
        matched = 0
        distance = []
        shortest = 0
        next_edge = []

        def augment(airport):
            neighbors = adjacency[airport]
            while next_edge[airport] < len(neighbors):
                factory = neighbors[next_edge[airport]]
                next_edge[airport] += 1
                partner = right_match[factory]

                if partner == -1:
                    if distance[airport] + 1 != shortest:
                        continue
                elif (
                    distance[partner] != distance[airport] + 1
                    or not augment(partner)
                ):
                    continue

                left_match[airport] = factory
                right_match[factory] = airport
                return True

            distance[airport] = -1
            return False

        while matched < n:
            distance = [-1] * n
            queue = []
            for airport in range(n):
                if left_match[airport] == -1:
                    distance[airport] = 0
                    queue.append(airport)

            shortest = n + 1
            for airport in queue:
                next_distance = distance[airport] + 1
                if next_distance > shortest:
                    continue

                for factory in adjacency[airport]:
                    partner = right_match[factory]
                    if partner == -1:
                        shortest = next_distance
                    elif next_distance < shortest and distance[partner] == -1:
                        distance[partner] = next_distance
                        queue.append(partner)

            if shortest == n + 1:
                return False

            next_edge = [0] * n
            for airport in range(n):
                if left_match[airport] == -1 and augment(airport):
                    matched += 1

        return True

    if not possible(m):
        print(-1)
        return

    low = n - 1
    high = m
    while high - low > 1:
        middle = (low + high) // 2
        if possible(middle):
            high = middle
        else:
            low = middle

    print(edges[high - 1][0])


if __name__ == "__main__":
    main()
